216	    pub fn background_spawn<R>(&self, future: impl Future<Output = R> + Send + 'static) -> Task<R>
217	    where
218	        R: Send + 'static,
219	    {
220	        self.background_executor.spawn(future)
221	    }
222	
223	    /// Get an async handle to the app.
