506	#[cfg(test)]
507	mod tests {
508	    use super::*;
509	    use crate::{FocusHandle, Focusable, div, prelude::*};
510	
511	    struct Counter {
512	        count: usize,
513	        focus_handle: FocusHandle,
514	    }
515	
516	    impl Counter {
517	        fn new(_window: &mut Window, cx: &mut Context<Self>) -> Self {
518	            let focus_handle = cx.focus_handle();
519	            Self {
520	                count: 0,
521	                focus_handle,
522	            }
523	        }
524	
